// Scenarios of docs/specs/public-directory.md about the photos of the cards,
// below the pages: "Only the photo generated by the server is rendered",
// "Photo weight does not break the 4G budget" and "The photo of an
// unpublished business is referenced on no public surface (v2)"; and of
// docs/specs/deployment.md, "Public media live in R2, in one bucket for
// production and one for dev and stage (v2)". The pages that render them are
// tested with the Container API (test/astro/business-card.test.ts) and end to
// end (test/e2e/photos.spec.ts).
import { env } from "cloudflare:workers";
import { eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it, vi } from "vite-plus/test";
import { BUSINESS_ID_LENGTH, newBusinessId } from "../../src/core/business/id.ts";
import { publishedCard, publishedCards } from "../../src/core/business/card.ts";
import { listedBusinesses } from "../../src/core/business/listing.ts";
import { businesses } from "../../src/core/db/schema/index.ts";
import {
  isPhotoKey,
  newPhotoKey,
  PHOTO_CACHE_CONTROL,
  PHOTO_CONTENT_TYPE,
  PHOTO_KEY_LENGTH,
  PHOTO_VARIANTS,
  photoObjectKey,
  photoObjectKeys,
  photoUrl,
} from "../../src/core/photos/photo.ts";
import { searchPublishedBusinesses } from "../../src/core/search/query.ts";
import { sitemapEntries } from "../../src/core/seo/sitemap.ts";
import {
  absolutePhotoUrl,
  businessPhoto,
  LOCAL_MEDIA_PATH,
  mediaBase,
  photoShareImage,
  serveLocalMedia,
} from "../../src/lib/media.ts";
import { cleanup, createFixture, db, type Fixture, insertBusiness } from "./fixtures.ts";

const KEY = "yya626vdevvbuxa5avc2n8e6";
const PROD = {
  ENVIRONMENT: "prod",
  SITE_URL: "https://enmirumbo.com",
  MEDIA_URL: "https://media.enmirumbo.com",
};
const LOCAL = { ENVIRONMENT: "local", SITE_URL: "http://localhost:4321", MEDIA_URL: "" };

describe("Only the photo generated by the server is rendered", () => {
  it("a photo key is what the server generates: 24 characters of the identifier alphabet", () => {
    for (let i = 0; i < 20; i += 1) {
      const key = newPhotoKey();
      expect(key).toHaveLength(PHOTO_KEY_LENGTH);
      expect(isPhotoKey(key)).toBe(true);
    }
    // It is never a business identifier.
    expect(PHOTO_KEY_LENGTH).not.toBe(BUSINESS_ID_LENGTH);
    expect(isPhotoKey(newBusinessId())).toBe(false);
  });

  // Scenarios: external reference stored by hand; `data:` or `javascript:` in
  // the reference; attempt to escape the storage
  it.for([
    "https://evil.example/pixel.png",
    "data:image/svg+xml,<svg onload=alert(1)>",
    "javascript:alert(1)",
    "../../etc/passwd",
    `../${KEY}`,
    "/etc/passwd",
    "photos/" + KEY,
    "hola",
    "",
    KEY.toUpperCase(),
    `${KEY}a`,
    KEY.slice(1),
    `${KEY.slice(0, 23)}0`,
  ])("a stored %j is no photo: no address is built", (stored) => {
    expect(isPhotoKey(stored)).toBe(false);
    expect(photoUrl("https://media.enmirumbo.com", stored, "card")).toBeNull();
    expect(businessPhoto(PROD, stored, "full")).toBeNull();
    expect(absolutePhotoUrl(PROD, stored, "full")).toBeNull();
    expect(photoShareImage(PROD, { name: "Negocio", photoKey: stored })).toBeNull();
  });

  it("no key, no photo", () => {
    expect(businessPhoto(PROD, null, "card")).toBeNull();
    expect(photoShareImage(PROD, { name: "Negocio", photoKey: null })).toBeNull();
  });

  it("the address is the media base, the photos prefix, the key and the variant", () => {
    expect(photoObjectKey(KEY, "card")).toBe(`photos/${KEY}/card.webp`);
    expect(photoObjectKeys(KEY)).toEqual([`photos/${KEY}/card.webp`, `photos/${KEY}/full.webp`]);
    expect(() => photoObjectKey("../x", "card")).toThrow();
    expect(businessPhoto(PROD, KEY, "card")).toEqual({
      src: `https://media.enmirumbo.com/photos/${KEY}/card.webp`,
      width: 400,
      height: 400,
    });
    expect(businessPhoto(PROD, KEY, "full")).toEqual({
      src: `https://media.enmirumbo.com/photos/${KEY}/full.webp`,
      width: 1200,
      height: 900,
    });
  });
});

describe("Photo weight does not break the 4G budget", () => {
  it("the variants fit the caps: 400px and 60 KB, 1200px and 250 KB on the longer side", () => {
    const { card, full } = PHOTO_VARIANTS;
    expect(Math.max(card.width, card.height)).toBeLessThanOrEqual(400);
    expect(card.maxBytes).toBeLessThanOrEqual(60 * 1024);
    expect(Math.max(full.width, full.height)).toBeLessThanOrEqual(1200);
    expect(full.maxBytes).toBeLessThanOrEqual(250 * 1024);
    // The listing card's slot is square; the card's photo is larger.
    expect(card.width).toBe(card.height);
    expect(full.width).toBeGreaterThan(card.width);
  });

  it("a variant is cached for a year by browsers and the CDN", () => {
    expect(PHOTO_CONTENT_TYPE).toBe("image/webp");
    expect(PHOTO_CACHE_CONTROL).toBe("public, max-age=31536000, immutable");
  });
});

describe("Public media live in R2, in one bucket for production and one for dev and stage (v2)", () => {
  it("a deployed environment takes its photos from its media hostname", () => {
    expect(mediaBase(PROD)).toBe("https://media.enmirumbo.com");
    expect(
      mediaBase({
        ...PROD,
        ENVIRONMENT: "dev",
        MEDIA_URL: "https://media-dev.enmirumbo.com",
      }),
    ).toBe("https://media-dev.enmirumbo.com");
  });

  it("locally, the local Worker's own path", () => {
    expect(mediaBase(LOCAL)).toBe(LOCAL_MEDIA_PATH);
    expect(businessPhoto(LOCAL, KEY, "card")?.src).toBe(`/_media/photos/${KEY}/card.webp`);
    // The share preview and the structured data need an absolute address.
    expect(absolutePhotoUrl(LOCAL, KEY, "full")).toBe(
      `http://localhost:4321/_media/photos/${KEY}/full.webp`,
    );
  });

  it("a deployed environment without a usable MEDIA_URL shows no photo, and says so once", () => {
    const log = vi.spyOn(console, "error").mockImplementation(() => {});
    try {
      for (const media of ["", "http://media.enmirumbo.com", "https://media.example/x"]) {
        expect(mediaBase({ ...PROD, ENVIRONMENT: "stage", MEDIA_URL: media }), media).toBeNull();
        expect(
          businessPhoto({ ...PROD, ENVIRONMENT: "stage", MEDIA_URL: media }, KEY, "card"),
        ).toBeNull();
      }
      expect(log).toHaveBeenCalledTimes(1);
      expect(String(log.mock.calls[0]?.[0])).toContain(
        'MEDIA_URL is missing or is not an https origin in the "stage"',
      );
    } finally {
      log.mockRestore();
    }
  });

  it("the share image of a card with a photo is its full variant, with its size and alt text", () => {
    expect(
      photoShareImage(PROD, { name: "Farmacia La Pastilla de Mentiras", photoKey: KEY }),
    ).toEqual({
      src: `https://media.enmirumbo.com/photos/${KEY}/full.webp`,
      width: 1200,
      height: 900,
      type: "image/webp",
      alt: "Foto de Farmacia La Pastilla de Mentiras",
    });
  });
});

describe("The local Worker serves the local media bucket under /_media/", () => {
  const key = photoObjectKey(newPhotoKey(), "card");
  const local = { ENVIRONMENT: "local", MEDIA: env.MEDIA };
  const get = (path: string, init: RequestInit = {}, host = "http://localhost:4321") =>
    serveLocalMedia(new Request(`${host}${path}`, init), local);

  beforeAll(async () => {
    await env.MEDIA.put(key, new Uint8Array([82, 73, 70, 70]), {
      httpMetadata: { contentType: PHOTO_CONTENT_TYPE, cacheControl: PHOTO_CACHE_CONTROL },
    });
  });

  afterAll(async () => {
    await env.MEDIA.delete(key);
  });

  it("an object answers with its bytes, its media type and its caching", async () => {
    const response = await get(`/_media/${key}`);
    expect(response?.status).toBe(200);
    expect(response?.headers.get("Content-Type")).toBe(PHOTO_CONTENT_TYPE);
    expect(response?.headers.get("Cache-Control")).toBe(PHOTO_CACHE_CONTROL);
    expect(new Uint8Array(await response!.arrayBuffer())).toEqual(new Uint8Array([82, 73, 70, 70]));

    const head = await get(`/_media/${key}`, { method: "HEAD" });
    expect(head?.status).toBe(200);
    expect(head?.headers.get("Content-Length")).toBe("4");
    expect(await head!.text()).toBe("");
  });

  // public-directory, "The photo of an unpublished business is referenced on
  // no public surface (v2)", scenario "the bucket does not list"
  it.for([
    "/_media",
    "/_media/",
    "/_media/photos/",
    `/_media/${key.split("/").slice(0, 2).join("/")}/`,
  ])("%s lists nothing", async (path) => {
    const response = await get(path);
    expect(response?.status).toBe(404);
    expect(await response!.text()).not.toContain("photos/");
  });

  it("an object that does not exist answers 404, and only GET and HEAD are served", async () => {
    expect((await get(`/_media/photos/${newPhotoKey()}/card.webp`))?.status).toBe(404);
    expect((await get(`/_media/${key}`, { method: "POST" }))?.status).toBe(405);
  });

  it("outside the local environment, off a loopback host or outside /_media/, it does not exist", async () => {
    const request = new Request(`http://localhost:4321/_media/${key}`);
    for (const environment of ["dev", "stage", "prod", undefined]) {
      expect(
        await serveLocalMedia(request, { ENVIRONMENT: environment, MEDIA: env.MEDIA }),
      ).toBeNull();
    }
    expect(await get(`/_media/${key}`, {}, "https://enmirumbo.com")).toBeNull();
    expect(await get("/hidalgo/tizayuca")).toBeNull();
    expect(await get("/_mediateca")).toBeNull();
  });
});

const STATE = "84";

describe("The photo of an unpublished business is referenced on no public surface (v2)", () => {
  let f: Fixture;
  const keys = {
    published: newPhotoKey(),
    inReview: newPhotoKey(),
    rejected: newPhotoKey(),
    unpublished: newPhotoKey(),
  };
  const ids: Record<keyof typeof keys, string> = {
    published: "",
    inReview: "",
    rejected: "",
    unpublished: "",
  };

  beforeAll(async () => {
    f = await createFixture(STATE);
    const now = new Date();
    ids.published = await insertBusiness(f, {
      name: "Fotografía Publicada de Prueba",
      status: "published",
      publishedAt: now,
      photoKey: keys.published,
    });
    ids.inReview = await insertBusiness(f, {
      name: "Fotografía En Revisión de Prueba",
      photoKey: keys.inReview,
    });
    ids.rejected = await insertBusiness(f, {
      name: "Fotografía Rechazada de Prueba",
      status: "rejected",
      rejectedAt: now,
      rejectionReason: "Motivo de prueba",
      photoKey: keys.rejected,
    });
    // Published, then unpublished: back in review.
    ids.unpublished = await insertBusiness(f, {
      name: "Fotografía Despublicada de Prueba",
      status: "published",
      publishedAt: now,
      photoKey: keys.unpublished,
    });
    await db((tx) =>
      tx
        .update(businesses)
        .set({ status: "in_review", publishedAt: null })
        .where(eq(businesses.id, ids.unpublished)),
    );
  });

  afterAll(() => cleanup(STATE));

  const hidden = () => [keys.inReview, keys.rejected, keys.unpublished];

  // Scenarios: a published card; a registration in review; unpublishing
  it("the listing, the search, the card and the sitemap name only the published card's key", async () => {
    const reads = await db(async (tx) => ({
      listing: await listedBusinesses(
        tx,
        { localityCode: f.localityA, categoryId: f.categoryId, zoneId: null },
        1,
      ),
      search: await searchPublishedBusinesses(
        tx,
        { code: f.localityA, name: "Pueblo Uno" },
        "fotografia",
        {
          limit: 100,
          offset: 0,
        },
      ),
      cards: await Promise.all(Object.values(ids).map((id) => publishedCard(tx, f.localityA, id))),
      sitemap: await sitemapEntries(tx),
      entries: await publishedCards(tx, f.localityA),
    }));

    expect(reads.listing.businesses.map(({ photoKey }) => photoKey)).toEqual([keys.published]);
    expect(reads.search?.map(({ photoKey }) => photoKey)).toEqual([keys.published]);
    expect(reads.cards.map((card) => card?.photoKey ?? null)).toEqual([
      keys.published,
      null,
      null,
      null,
    ]);
    const everything = JSON.stringify(reads);
    expect(everything).toContain(keys.published);
    for (const key of hidden()) expect(everything).not.toContain(key);
    // The sitemap never names a photo, not even a published one.
    expect(JSON.stringify(reads.sitemap)).not.toContain(keys.published);
  });
});
